EXPLAIN SELECT x FROM t;

EXPLAIN QUERY PLAN SELECT x FROM t WHERE x = 1;

EXPLAIN QUERY PLAN INSERT INTO t (x) VALUES (1);

EXPLAIN QUERY PLAN UPDATE t SET x = 2 WHERE x = 1;

EXPLAIN QUERY PLAN DELETE FROM t WHERE x = 1;

EXPLAIN QUERY PLAN
WITH values_cte AS (SELECT x FROM t)
SELECT * FROM values_cte;

EXPLAIN CREATE TABLE new_table (x INTEGER);

EXPLAIN QUERY PLAN CREATE TABLE new_table (x INTEGER);
